/**
 * Assinatura manuscrita "Gustavo Leonel" em SVG vetorial.
 *
 * - Tracos vetorizados da assinatura real (imgs/signature.png),
 *   reconstruidos na ordem de escrita, da esquerda para a direita
 * - Comprimento real de cada path via getTotalLength(); duração proporcional
 *   (velocidade de caneta constante: letras complexas demoram mais)
 * - Ponta luminosa discreta acompanha o traço ativo e some no final
 * - Replay automático: toda vez que o card sai da viewport a assinatura é
 *   apagada; ao voltar (ou recarregar a página), ela é reescrita do zero
 */
export function SignatureLogo({ className = '' }: SignatureLogoProps) {
  const wrapRef = useRef<HTMLSpanElement>(null);
  const pathsRef = useRef(new Map<string, SVGPathElement>());
  const tipRef = useRef<SVGCircleElement>(null);
  const inViewRef = useRef(false);
  /** 0 = apagada; >0 = escrevendo (incrementa a cada reentrada) */
  const [cycle, setCycle] = useState(0);

  useEffect(() => {
    const el = wrapRef.current;
    if (!el) return;
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
      return;
    }
    const io = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (entry.isIntersecting && !inViewRef.current) {
            inViewRef.current = true;
            setCycle((c) => c + 1);
          } else if (!entry.isIntersecting && inViewRef.current) {
            inViewRef.current = false;
            setCycle(0);
          }
        }
      },
      { threshold: 0.4 },
    );
    io.observe(el);
    return () => io.disconnect();
  }, []);

  useLayoutEffect(() => {
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
      return;
    }

    const items = STROKES.map((s) => ({
      def: s,
      el: pathsRef.current.get(s.id),
    })).filter(
      (x): x is { def: StrokeDef; el: SVGPathElement } => x.el != null,
    );
    if (items.length === 0) return;

    // Comprimento real de cada traço — nada de valor arbitrário.
    const lens = items.map(({ el }) => el.getTotalLength());

    // Fora da viewport (ou antes da primeira entrada): tudo apagado.
    if (cycle === 0) {
      for (const [i, { el }] of items.entries()) {
        el.style.strokeDasharray = `${lens[i]}`;
        el.style.strokeDashoffset = `${lens[i]}`;
      }
      if (tipRef.current) tipRef.current.style.opacity = '0';
      return;
    }

    // Orçamento de tempo: total menos pausas e trechos de duração fixa.
    const gaps = items.map(({ def }) => def.gap);
    const fixed =
      items.reduce(
        (acc, { def }) => acc + (def.fixedDur ?? 0) + (def.extraDelay ?? 0),
        0,
      ) + gaps.reduce((a, b) => a + b, 0);
    const inkTotal = items.reduce(
      (acc, { def }, i) => acc + (def.fixedDur != null ? 0 : lens[i]),
      0,
    );
    const speed = inkTotal / Math.max(1, TOTAL_MS - fixed);

    // Timeline: cada letra começa quando a anterior termina (+ gap).
    const starts: number[] = [];
    const durs: number[] = [];
    let cursor = 0;
    items.forEach(({ def }, i) => {
      cursor += def.extraDelay ?? 0;
      starts[i] = cursor;
      durs[i] = def.fixedDur ?? lens[i] / speed;
      cursor += durs[i] + def.gap;
    });
    const end = cursor;

    for (const [i, { el }] of items.entries()) {
      el.style.strokeDasharray = `${lens[i]}`;
      el.style.strokeDashoffset = `${lens[i]}`;
    }

    const anims = items.map(({ el }, i) =>
      el.animate(
        [{ strokeDashoffset: lens[i] }, { strokeDashoffset: 0 }],
        {
          duration: durs[i],
          delay: starts[i],
          easing: 'linear',
          fill: 'forwards',
        },
      ),
    );

    // Ponta da caneta: brilho discreto que percorre o traço ativo.
    const tip = tipRef.current;
    let raf = 0;
    if (tip) {
      const t0 = performance.now();
      let lastX = 0;
      let lastY = 0;
      let hasLast = false;
      const tick = (now: number) => {
        const e = now - t0;
        if (e >= end + 150) {
          tip.style.opacity = '0';
          return;
        }
        let active = -1;
        for (let i = 0; i < items.length; i++) {
          if (e >= starts[i] && e <= starts[i] + durs[i]) {
            active = i;
            break;
          }
        }
        if (active >= 0) {
          const p = Math.min(1, Math.max(0, (e - starts[active]) / durs[active]));
          const pt = items[active].el.getPointAtLength(p * lens[active]);
          lastX = pt.x;
          lastY = pt.y;
          hasLast = true;
          tip.setAttribute('cx', `${pt.x}`);
          tip.setAttribute('cy', `${pt.y}`);
          tip.style.opacity = e < 120 ? `${(e / 120) * 0.9}` : '0.9';
        } else if (hasLast) {
          // intervalo entre letras: mantém a ponta onde a caneta parou
          tip.setAttribute('cx', `${lastX}`);
          tip.setAttribute('cy', `${lastY}`);
          tip.style.opacity = '0.9';
        }
        raf = requestAnimationFrame(tick);
      };
      raf = requestAnimationFrame(tick);
    }

    return () => {
      for (const a of anims) a.cancel();
      cancelAnimationFrame(raf);
    };
  }, [cycle]);

  return (
    <span ref={wrapRef} className={`${styles.wrap} ${className}`}>
      <svg
        className={styles.svg}
        viewBox="116 24 592 136"
        fill="none"
        role="img"
        aria-label="Gustavo Leonel"
        aria-hidden={false}
      >
        <title>Gustavo Leonel</title>
        {STROKES.map((s) => (
          <path
            key={s.id}
            ref={(el) => {
              if (el) pathsRef.current.set(s.id, el);
              else pathsRef.current.delete(s.id);
            }}
            className={styles.path}
            style={{
              strokeWidth: s.w,
              ...(s.opacity != null ? { opacity: s.opacity } : null),
            }}
            d={s.d}
          />
        ))}
        <circle ref={tipRef} className={styles.tip} r={3.2} cx={0} cy={0} />
      </svg>
    </span>
  );
}
